from ta_emss.utilities.trs.commands.emssim import EmssimCommand


class Parents(EmssimCommand):
    def __init__(self, method="parents", timeout=60, rpc_connection_name='localRPC'):
        super(Parents, self).__init__(method, timeout, rpc_connection_name)
        self.params = None

    def on_new_data(self, **data):
        data = super(Parents, self).on_new_data(**data)
        if "pddb_parents" in data:
            self._ret["pddb_parents"] = data["pddb_parents"]
        if "user_parents" in data:
            self._ret["user_parents"] = data["user_parents"]
        if ("status" in data):
            self._ret["status"] = data["status"]
